#include <iostream>
#include <iomanip>
int main() {
    double pi = 3.14159265358979;
    std::cout << "default: " << pi << '\n';
    std::cout << "fixed2: " << std::fixed << std::setprecision(2) << pi << '\n';
    std::cout << std::defaultfloat << "sig4: " << std::setprecision(4) << pi << '\n';
